create table public.mystream_renewal_emails(user_id uuid not null references auth.users(id) on delete cascade,pro_until timestamptz not null,kind text not null check(kind in ('due','expired')),sent_at timestamptz,primary key(user_id,pro_until,kind)); alter table public.mystream_renewal_emails enable row level security; revoke all on public.mystream_renewal_emails from public,anon,authenticated; grant all on public.mystream_renewal_emails to service_role;
